--[[
  Fisch Hub 2.0
  Bundled build. Generated by build.py from src/*.lua - do not edit this
  file directly, edit the module and rebuild.

  Toggle panel: RightControl.
  Console API: getgenv().FischHub
]]

local __modules = {}
local function __require(name)
	local module = __modules[name]
	assert(module, "module not loaded: " .. tostring(name))
	return module
end

__modules["env"] = (function()
-- env: services, executor capability detection, logging
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")
local UserInputService = game:GetService("UserInputService")
local VirtualUser = game:GetService("VirtualUser")
local VirtualInputManager = game:GetService("VirtualInputManager")
local Lighting = game:GetService("Lighting")
local CoreGui = game:GetService("CoreGui")

local M = {
	Players = Players,
	ReplicatedStorage = ReplicatedStorage,
	RunService = RunService,
	TweenService = TweenService,
	UserInputService = UserInputService,
	VirtualUser = VirtualUser,
	VirtualInputManager = VirtualInputManager,
	Lighting = Lighting,
	CoreGui = CoreGui,
}

M.has = {
	drawing    = typeof(Drawing) == "table" and Drawing.new ~= nil,
	writefile  = typeof(writefile) == "function",
	readfile   = typeof(readfile) == "function",
	isfile     = typeof(isfile) == "function",
	isfolder   = typeof(isfolder) == "function",
	makefolder = typeof(makefolder) == "function",
	loadstring = typeof(loadstring) == "function",
	hook       = typeof(hookfunction) == "function",
	getgenv    = typeof(getgenv) == "function",
	proximity  = typeof(fireproximityprompt) == "function",
	mouse1     = typeof(mouse1press) == "function",
	httppost   = typeof(request) == "function" or typeof(http_request) == "function",
	queue      = typeof(queue_on_teleport) == "function" or typeof(TeleportToPlaceInstance) == "function",
}

repeat task.wait() until Players.LocalPlayer
M.LocalPlayer = Players.LocalPlayer
M.Character = function()
	return M.LocalPlayer.Character or M.LocalPlayer.CharacterAdded:Wait()
end
M.Humanoid = function()
	local character = M.LocalPlayer.Character
	return character and character:FindFirstChildOfClass("Humanoid")
end
M.Root = function()
	local character = M.LocalPlayer.Character
	return character and character:FindFirstChild("HumanoidRootPart")
end

local startedAt = os.clock()
M.executor = "unknown"
if typeof(identifyexecutor) == "function" then
	local ok, name = pcall(identifyexecutor)
	if ok and type(name) == "string" then M.executor = name end
end

function M.log(fmt, ...)
	local text
	if select("#", ...) > 0 then
		local ok, formatted = pcall(string.format, fmt, ...)
		text = ok and formatted or tostring(fmt)
	else
		text = tostring(fmt)
	end
	print(string.format("[FischHub] %s", text))
end

function M.uptime()
	return os.clock() - startedAt
end

return M

end)()

__modules["util"] = (function()
-- util: string matching, timers, a heartbeat scheduler, small math helpers
local env = __require("env")

local M = {}

function M.matches(name, patterns)
	if type(name) ~= "string" then return false end
	local lower = name:lower()
	for _, pattern in ipairs(patterns) do
		if lower:find(pattern, 1, true) then return true end
	end
	return false
end

function M.any(...)
	for _, value in ipairs({ ... }) do
		if value then return value end
	end
	return nil
end

function M.clamp(value, low, high)
	if value < low then return low end
	if value > high then return high end
	return value
end

function M.round(value, places)
	local factor = 10 ^ (places or 0)
	return math.floor(value * factor + 0.5) / factor
end

function M.distance(a, b)
	return (a - b).Magnitude
end

function M.now()
	return os.clock()
end

--------------------------------------------------------------------------------
-- scheduler
--
-- One heartbeat connection drives every periodic task. Each task declares an
-- interval and gets an accumulator, so a slow task cannot starve a fast one and
-- nothing spins in its own `while true do task.wait()` competing for frames.
--------------------------------------------------------------------------------

local Scheduler = { tasks = {}, index = {}, connection = nil }

function Scheduler.add(spec)
	assert(type(spec.run) == "function", "task needs a run function")
	spec.interval = spec.interval or 0.1
	spec.accumulator = spec.interval
	spec.runs = 0
	spec.errors = 0
	Scheduler.tasks[#Scheduler.tasks + 1] = spec
	if spec.name then Scheduler.index[spec.name] = spec end
	return spec
end

function Scheduler.remove(name)
	local spec = Scheduler.index[name]
	if not spec then return false end
	for i, entry in ipairs(Scheduler.tasks) do
		if entry == spec then
			table.remove(Scheduler.tasks, i)
			break
		end
	end
	Scheduler.index[name] = nil
	return true
end

function Scheduler.start()
	if Scheduler.connection then return end
	Scheduler.connection = env.RunService.Heartbeat:Connect(function(delta)
		for _, spec in ipairs(Scheduler.tasks) do
			if not spec.paused then
				spec.accumulator = spec.accumulator + delta
				if spec.accumulator >= spec.interval then
					spec.accumulator = 0
					spec.runs = spec.runs + 1
					local ok, err = pcall(spec.run)
					if not ok then
						spec.errors = spec.errors + 1
						if spec.errors <= 3 then
							env.log("task %s error: %s", spec.name or "?", tostring(err))
						end
					end
				end
			end
		end
	end)
end

function Scheduler.pause(name, paused)
	local spec = Scheduler.index[name]
	if spec then spec.paused = paused end
end

function Scheduler.stats()
	local rows = {}
	for _, spec in ipairs(Scheduler.tasks) do
		rows[#rows + 1] = string.format("%s %dms", spec.name or "?", math.floor(spec.interval * 1000))
	end
	return table.concat(rows, ", ")
end

M.scheduler = Scheduler

function M.task(name, interval, run)
	return Scheduler.add({ name = name, interval = interval, run = run })
end

function M.spawn(fn)
	local ok, err = pcall(fn)
	if not ok then env.log("spawn error: %s", tostring(err)) end
end

function M.retry(fn, attempts, delay)
	attempts = attempts or 3
	for attempt = 1, attempts do
		local ok, result = pcall(fn)
		if ok then return result end
		if attempt < attempts then task.wait(delay or 0.25) end
	end
	return nil
end

--------------------------------------------------------------------------------
-- serialization for the config file
--------------------------------------------------------------------------------

function M.serialize(value, indent)
	indent = indent or ""
	local kind = typeof(value)
	if kind == "table" then
		local parts = {}
		local keys = {}
		for key in pairs(value) do keys[#keys + 1] = key end
		table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
		for _, key in ipairs(keys) do
			local keyText = (type(key) == "string" and key:match("^[%a_][%w_]*$")) and key or ("[" .. M.serialize(key) .. "]")
			parts[#parts + 1] = indent .. "  " .. keyText .. " = " .. M.serialize(value[key], indent .. "  ")
		end
		return "{\n" .. table.concat(parts, ",\n") .. "\n" .. indent .. "}"
	elseif kind == "string" then
		return string.format("%q", value)
	elseif kind == "Vector3" then
		return string.format("Vector3.new(%.3f, %.3f, %.3f)", value.X, value.Y, value.Z)
	elseif kind == "boolean" or kind == "number" then
		return tostring(value)
	end
	return "nil"
end

return M

end)()

__modules["config"] = (function()
-- config: defaults, persistence, profiles
local env = __require("env")
local util = __require("util")

local M = {}

local DEFAULTS = {
	-- fishing
	autoCast = true,
	autoReel = true,
	instantReel = true,
	autoRod = true,
	castDelay = 0.9,
	reelMode = "Auto",        -- Auto | Tool | Remote | Input
	keepDistance = 0,         -- 0 = off, otherwise hold this range from others

	-- economy
	autoSell = true,
	sellInterval = 120,
	autoAppraise = false,
	appraiseInterval = 300,
	autoBuyBait = false,
	autoQuest = false,
	questInterval = 120,

	-- movement
	walkSpeed = 16,
	jumpPower = 50,
	fly = false,
	noclip = false,
	infOxygen = false,
	tpSpeed = 200,

	-- esp
	esp = false,
	espPlayers = true,
	espFish = true,
	espNpcs = false,
	espChests = true,
	espRange = 600,
	espBoxes = true,
	espLabels = true,

	-- stealth
	stealth = true,
	humanize = true,
	pauseOnPlayers = true,
	proximityRadius = 140,
	teleportGuard = true,
	rateCap = 14,          -- catches per minute ceiling
	imperfection = 0.07,   -- chance of a deliberate slip per catch
	sessionMinutes = 55,
	breakMinutes = 7,
	panicKey = "Delete",

	-- misc
	antiAfk = true,
	antiMod = true,
	autoRejoin = false,
	notify = true,
	debug = false,

	-- ui
	keybind = "RightControl",
}

local PATTERNS = {
	rod       = { "rod", "fishing rod" },
	reel      = { "reel", "catch", "fish", "hook" },
	cast      = { "cast", "throw", "fish" },
	sell      = { "sell", "shop", "vendor", "merchant", "trader" },
	appraise  = { "appraise", "appraiser", "appraisal", "evaluate" },
	quest     = { "quest", "mission", "claim", "reward" },
	bait      = { "bait", "buy", "purchase" },
	minigame  = { "fish", "reel", "catch", "mini", "bobber", "bite", "hook" },
	marker    = { "marker", "indicator", "pointer", "needle", "zone", "target", "perfect", "cursor" },
	track     = { "bar", "track", "zone", "area", "gauge", "meter" },
	espFish   = { "fish", "bobber", "crate", "chest", "loot", "item" },
	espNpc    = { "npc", "villager", "merchant", "angler", "keeper" },
	oxygen    = { "oxygen", "air", "breath" },
}

M.patterns = PATTERNS

local Config = {}
for key, value in pairs(DEFAULTS) do Config[key] = value end
M.data = Config

local FILE = "fischhub/config.lua"

function M.get(key)
	return Config[key]
end

function M.set(key, value)
	Config[key] = value
	M.save()
end

function M.save()
	if not (env.has.writefile and env.has.isfolder and env.has.makefolder) then
		if not env.has.writefile then return false end
	end
	local ok, err = pcall(function()
		local folder = "fischhub"
		if env.has.isfolder and not isfolder(folder) then
			makefolder(folder)
		end
		if env.has.makefolder and not env.has.isfolder then
			makefolder(folder)
		end
		writefile(FILE, "return " .. util.serialize(Config) .. "\n")
	end)
	if not ok then env.log("config save failed: %s", tostring(err)) end
	return ok
end

function M.load()
	if not (env.has.readfile and env.has.isfile) then return false end
	local ok, data = pcall(function()
		if not isfile(FILE) then return nil end
		if env.has.loadstring then
			return loadstring(readfile(FILE))()
		end
		return nil
	end)
	if ok and type(data) == "table" then
		for key, value in pairs(data) do
			if DEFAULTS[key] ~= nil and typeof(DEFAULTS[key]) == typeof(value) then
				Config[key] = value
			end
		end
		return true
	end
	return false
end

function M.reset()
	for key, value in pairs(DEFAULTS) do Config[key] = value end
	return M.save()
end

function M.defaults()
	return DEFAULTS
end

function M.profilePath(name)
	local safe = (tostring(name):gsub("[^%w_-]", "_"))
	return string.format("fischhub/profile-%s.lua", safe)
end

function M.saveProfile(name)
	if not env.has.writefile then return false end
	return pcall(writefile, M.profilePath(name), "return " .. util.serialize(Config) .. "\n")
end

function M.loadProfile(name)
	if not (env.has.readfile and env.has.isfile) then return false end
	local path = M.profilePath(name)
	if not isfile(path) then return false end
	local ok, data = pcall(function() return loadstring(readfile(path))() end)
	if not (ok and type(data) == "table") then return false end
	for key, value in pairs(data) do
		if DEFAULTS[key] ~= nil and typeof(DEFAULTS[key]) == typeof(value) then
			Config[key] = value
		end
	end
	return true
end

return M

end)()

__modules["scanner"] = (function()
-- scanner: instance discovery, cached and diffed
local env = __require("env")
local util = __require("util")
local config = __require("config")

local P = config.patterns

local M = {
	remotes = { all = {}, cast = nil, reel = nil, sell = nil, appraise = nil },
	overrides = { cast = nil, reel = nil, sell = nil, appraise = nil },
	clickDetectors = {},
	prompts = { sell = {}, appraise = {}, quest = {}, bait = {} },
	landmarks = {},
	mapName = "",
	lastScan = 0,
	generation = 0,
}

-- Rod preference order. Higher index wins. Edit freely: the hub equips the
-- best rod in the backpack by this list, and falls through to the first rod it
-- finds when nothing matches. Ordered oldest to newest progression.
local ROD_ORDER = {
	"old rod", "flimsy rod", "training rod", "fast rod", "carbon rod",
	"lucky rod", "steady rod", "plastic rod", "river rod", "arctic rod",
	"stone rod", "fossil rod", "solar rod", "magma rod", "depth rod",
	"warrior rod", "mythic rod", "leviathan", "rod of the sea",
	"rod of the depths", "heaven's rod", "challenger's rod",
}

function M.rodRank(name)
	local lower = name:lower()
	for index, entry in ipairs(ROD_ORDER) do
		if lower:find(entry, 1, true) then return index end
	end
	return 0
end

function M.bestRod()
	local candidates = {}
	local function collect(container)
		if not container then return end
		for _, item in ipairs(container:GetChildren()) do
			if item:IsA("Tool") and util.matches(item.Name, P.rod) then
				candidates[#candidates + 1] = item
			end
		end
	end
	collect(env.LocalPlayer.Character)
	collect(env.LocalPlayer:FindFirstChildOfClass("Backpack"))

	if #candidates == 0 then return nil end
	table.sort(candidates, function(a, b)
		local rankA, rankB = M.rodRank(a.Name), M.rodRank(b.Name)
		if rankA ~= rankB then return rankA > rankB end
		return a.Name < b.Name
	end)
	return candidates[1]
end

local function scanRemotes()
	local all = {}
	local found = { cast = nil, reel = nil, sell = nil, appraise = nil }
	for _, obj in ipairs(env.ReplicatedStorage:GetDescendants()) do
		if obj:IsA("RemoteEvent") or obj:IsA("RemoteFunction") or obj:IsA("UnreliableRemoteEvent") then
			all[#all + 1] = obj
			if not found.cast and util.matches(obj.Name, P.cast) then found.cast = obj end
			if not found.reel and util.matches(obj.Name, P.reel) then found.reel = obj end
			if not found.sell and util.matches(obj.Name, P.sell) then found.sell = obj end
			if not found.appraise and util.matches(obj.Name, P.appraise) then found.appraise = obj end
		end
	end
	-- Learned assignments win over name-pattern guesses and survive rescans.
	for kind, override in pairs(M.overrides) do
		if override then found[kind] = override end
	end

	M.remotes = { all = all, cast = found.cast, reel = found.reel, sell = found.sell, appraise = found.appraise }
end

function M.setRemote(kind, remote)
	M.overrides[kind] = remote
	if M.remotes[kind] ~= nil or true then
		M.remotes[kind] = remote
	end
end

local function anchorPart(prompt)
	local anchor = prompt.Parent
	local depth = 0
	while anchor and depth < 4 do
		if anchor:IsA("BasePart") then return anchor.Position end
		if anchor:IsA("Model") then
			local primary = anchor.PrimaryPart or anchor:FindFirstChildWhichIsA("BasePart", true)
			if primary then return primary.Position end
		end
		anchor = anchor.Parent
		depth = depth + 1
	end
	return nil
end

local function scanPrompts()
	local buckets = { sell = {}, appraise = {}, quest = {}, bait = {} }
	for _, obj in ipairs(workspace:GetDescendants()) do
		if obj:IsA("ProximityPrompt") then
			local ownerName = obj.Parent and obj.Parent.Name or ""
			local position = anchorPart(obj)
			local record = { prompt = obj, position = position, label = obj.ObjectText ~= "" and obj.ObjectText or obj.ActionText }
			if util.matches(obj.Name, P.sell) or util.matches(ownerName, P.sell) then
				table.insert(buckets.sell, record)
			end
			if util.matches(obj.Name, P.appraise) or util.matches(ownerName, P.appraise) then
				table.insert(buckets.appraise, record)
			end
			if util.matches(obj.Name, P.quest) or util.matches(ownerName, P.quest) then
				table.insert(buckets.quest, record)
			end
			if util.matches(obj.Name, P.bait) or util.matches(ownerName, P.bait) then
				table.insert(buckets.bait, record)
			end
		end
	end
	M.prompts = buckets
end

local function scanClickDetectors()
	local buckets = { sell = {}, appraise = {}, quest = {}, bait = {} }
	for _, obj in ipairs(workspace:GetDescendants()) do
		if obj:IsA("ClickDetector") then
			local owner = obj.Parent
			local ownerName = owner and owner.Name or ""
			local position
			if owner then
				if owner:IsA("BasePart") then
					position = owner.Position
				else
					local part = owner:FindFirstChildWhichIsA("BasePart", true)
					position = part and part.Position
				end
			end
			local record = { detector = obj, position = position, label = ownerName }
			if util.matches(obj.Name, P.sell) or util.matches(ownerName, P.sell) then
				table.insert(buckets.sell, record)
			end
			if util.matches(obj.Name, P.appraise) or util.matches(ownerName, P.appraise) then
				table.insert(buckets.appraise, record)
			end
			if util.matches(obj.Name, P.quest) or util.matches(ownerName, P.quest) then
				table.insert(buckets.quest, record)
			end
			if util.matches(obj.Name, P.bait) or util.matches(ownerName, P.bait) then
				table.insert(buckets.bait, record)
			end
		end
	end
	M.clickDetectors = buckets
end

local function scanLandmarks()
	local map = {}
	for _, obj in ipairs(workspace:GetDescendants()) do
		if obj:IsA("BasePart") and #obj.Name > 2 then
			local key = obj.Name:lower()
			if not map[key] then map[key] = obj.Position end
		elseif obj:IsA("Model") and #obj.Name > 2 then
			local key = obj.Name:lower()
			if not map[key] then
				local primary = obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart", true)
				if primary then map[key] = primary.Position end
			end
		end
	end
	M.landmarks = map
end

local function nearest(records)
	local origin = env.Root() and env.Root().Position
	if not origin then return records[1] end
	local best, bestDistance = nil, math.huge
	for _, record in ipairs(records) do
		if record.position then
			local distance = (record.position - origin).Magnitude
			if distance < bestDistance then
				best, bestDistance = record, distance
			end
		end
	end
	return best or records[1]
end

function M.nearestPrompt(kind)
	local records = M.prompts[kind]
	if not records or #records == 0 then return nil end
	return nearest(records)
end

function M.landmark(needle)
	if not needle or needle == "" then return nil end
	local key = needle:lower()
	if M.landmarks[key] then return M.landmarks[key] end
	for name, position in pairs(M.landmarks) do
		if name:find(key, 1, true) then return position end
	end
	return nil
end

function M.refresh(force)
	local now = util.now()
	if not force and now - M.lastScan < 3 then return end
	M.lastScan = now
	M.generation = M.generation + 1

	pcall(scanRemotes)
	pcall(scanPrompts)
	pcall(scanClickDetectors)
	pcall(scanLandmarks)

	local placeId = game.PlaceId
	M.mapName = tostring(placeId)
	if game:GetService("MarketplaceService") then
		local ok, info = pcall(function() return game:GetService("MarketplaceService"):GetProductInfo(placeId) end)
		if ok and info and info.Name then M.mapName = info.Name end
	end
end

function M.summary()
	return string.format(
		"remotes:%d reel:%s cast:%s sell:%s prompts:sell%d app%d",
		#M.remotes.all,
		M.remotes.reel and M.remotes.reel.Name or "-",
		M.remotes.cast and M.remotes.cast.Name or "-",
		M.remotes.sell and M.remotes.sell.Name or "-",
		#M.prompts.sell,
		#M.prompts.appraise
	)
end

util.task("scanner", 3, function() M.refresh() end)

return M

end)()

__modules["stealth"] = (function()
-- stealth: make automated behaviour statistically boring
--
-- Detection is mostly statistics and reports, not injection. This module
-- attacks both:
--
--   variance     every interval drawn from a distribution, never a constant
--   presence     stops while a player can actually see you, resumes when clear
--   pacing       rolling rate cap, work/break cycles, daily session shape
--   imperfection deliberate missed catches so the success rate is not 100%
--   teleport     refuses to blink inside someone's line of sight
--   fingerprint  per-session constants drawn at boot, so two sessions differ
--   panic        one key wipes the surface: features off, UI hidden, ESP gone
local env = __require("env")
local util = __require("util")
local config = __require("config")

local M = {
	active = true,
	breaks = 0,
	lastCatch = 0,
	catches = {},
	sessionStart = util.now(),
	breakUntil = 0,
	blockedReason = nil,
	blockedBy = nil,
	panic = false,
	visibleToPlayer = false,
	proximity = {},
}

-- Per-session fingerprint. Drawn once at load, so no two runs of the hub look
-- identical in timing even with the same settings.
M.fingerprint = {
	castScale = 0.85 + math.random() * 0.4,
	reelLeadScale = 0.8 + math.random() * 0.5,
	slipBias = 0.7 + math.random() * 0.6,
	paceScale = 0.9 + math.random() * 0.25,
}

--------------------------------------------------------------------------------
-- distributions
--------------------------------------------------------------------------------

-- Jittered value with a soft lower bound. The sum of two uniforms is a cheap
-- triangular distribution: most draws land near the middle, few at the edges.
function M.jitter(base, spread)
	spread = spread or 0.25
	if not config.get("humanize") then return base end
	local wobble = (math.random() + math.random() - 1) * spread
	return math.max(base * (1 + wobble), 0.02)
end

function M.pause()
	local base = config.get("humanize") and math.random(120, 900) / 1000 or 0
	if base > 0 then task.wait(base) end
	return base
end

--------------------------------------------------------------------------------
-- presence
--------------------------------------------------------------------------------

local function rootOf(player)
	local character = player.Character
	return character and character:FindFirstChild("HumanoidRootPart")
end

local function lineOfSight(fromPart, toPart)
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	params.FilterDescendantsInstances = {
		env.LocalPlayer.Character,
		toPart.Parent,
	}
	local result = workspace:Raycast(fromPart.Position, toPart.Position - fromPart.Position, params)
	return result == nil
end

function M.scanPresence()
	local myRoot = rootOf(env.LocalPlayer)
	if not myRoot then return false, nil end

	local radius = config.get("proximityRadius")
	local nearestPlayer, nearestDistance = nil, math.huge
	local visible = false

	for _, player in ipairs(env.Players:GetPlayers()) do
		if player ~= env.LocalPlayer then
			local other = rootOf(player)
			if other then
				local distance = (other.Position - myRoot.Position).Magnitude
				if distance <= radius then
					M.proximity[player] = distance
					if distance < nearestDistance then
						nearestPlayer, nearestDistance = player, distance
					end
					if not visible and distance < radius * 0.8 then
						local ok, line = pcall(lineOfSight, myRoot, other)
						if ok and line then visible = true end
					end
				else
					M.proximity[player] = nil
				end
			end
		end
	end

	M.visibleToPlayer = visible
	M.nearest = nearestPlayer
	M.nearestDistance = nearestDistance < math.huge and nearestDistance or nil
	return visible, nearestPlayer
end

--------------------------------------------------------------------------------
-- rate limiting
--------------------------------------------------------------------------------

local function pruneCatches(now)
	while #M.catches > 0 and now - M.catches[1] > 60 do
		table.remove(M.catches, 1)
	end
end

function M.rateLimited()
	local now = util.now()
	pruneCatches(now)
	local cap = math.floor(config.get("rateCap") * M.fingerprint.paceScale)
	return #M.catches >= cap, #M.catches, cap
end

function M.noteCatch()
	local now = util.now()
	M.catches[#M.catches + 1] = now
	M.lastCatch = now
	pruneCatches(now)
end

-- Deliberate slip. A bot that lands every single catch at the same interval is
-- a beacon; a 5-10% failure rate is what a person actually looks like.
function M.shouldSlip()
	local chance = config.get("imperfection") * M.fingerprint.slipBias
	if chance <= 0 then return false end
	return math.random() < chance
end

--------------------------------------------------------------------------------
-- session shape
--------------------------------------------------------------------------------

local function sessionElapsedMinutes()
	return (util.now() - M.sessionStart) / 60
end

function M.updateSession(now)
	if M.breakUntil > 0 and now >= M.breakUntil then
		M.breakUntil = 0
		M.sessionStart = now
	end

	if M.breakUntil == 0 then
		local length = config.get("sessionMinutes")
		if length > 0 and sessionElapsedMinutes() >= length * (0.9 + math.random() * 0.25) then
			local breakLength = config.get("breakMinutes")
			M.breakUntil = now + breakLength * 60 * (0.7 + math.random() * 0.8)
			M.breaks = M.breaks + 1
			env.log("stealth: taking a %d minute break", breakLength)
		end
	end
end

--------------------------------------------------------------------------------
-- gate
--------------------------------------------------------------------------------

function M.blocked()
	M.blockedReason = nil
	M.blockedBy = nil

	if M.panic then
		M.blockedReason = "panic"
		return true
	end
	if not config.get("stealth") then return false end

	local now = util.now()
	M.updateSession(now)

	if M.breakUntil > 0 then
		M.blockedReason = "break"
		return true
	end

	local limited = M.rateLimited()
	if limited then
		M.blockedReason = "rate"
		return true
	end

	if config.get("pauseOnPlayers") then
		local visible, player = M.scanPresence()
		if visible and player then
			M.blockedReason = "seen"
			M.blockedBy = player.Name
			return true
		end
	end

	return false
end

function M.teleportAllowed(target)
	if not config.get("stealth") or not config.get("teleportGuard") then return true end
	local myRoot = rootOf(env.LocalPlayer)
	if not myRoot then return true end
	if not target then return true end

	local range = config.get("proximityRadius")
	for _, player in ipairs(env.Players:GetPlayers()) do
		if player ~= env.LocalPlayer then
			local other = rootOf(player)
			if other then
				local destination = Vector3.new(target.X, target.Y, target.Z)
				if (other.Position - destination).Magnitude < range then
					return false, player.Name
				end
			end
		end
	end
	return true
end

--------------------------------------------------------------------------------
-- panic
--------------------------------------------------------------------------------

function M.engagePanic()
	M.panic = true
	config.set("autoCast", false)
	config.set("autoReel", false)
	config.set("autoSell", false)
	config.set("autoAppraise", false)
	config.set("autoQuest", false)
	config.set("esp", false)
	config.set("fly", false)
	config.set("noclip", false)
	pcall(function() __require("motion").stopFly() end)
	pcall(function() __require("esp").clear() end)
	pcall(function() __require("ui").hide() end)
	pcall(function() __require("ui").notify("panic - everything off", "bad") end)
end

function M.releasePanic()
	M.panic = false
end

function M.status()
	if M.panic then return "PANIC" end
	if not config.get("stealth") then return "off" end
	if M.breakUntil > 0 then
		return string.format("break %ds", math.max(0, math.floor(M.breakUntil - util.now())))
	end
	local _, count, cap = M.rateLimited()
	if M.blockedReason == "seen" then return "hidden:" .. (M.blockedBy or "?") end
	return string.format("%d/%d per min", count, cap)
end

util.task("stealth", 1, function()
	if config.get("stealth") then
		pcall(M.scanPresence)
	else
		M.visibleToPlayer = false
	end
end)

return M

end)()

__modules["motion"] = (function()
-- motion: walk speed, jump, fly, noclip, oxygen, tween teleports
local env = __require("env")
local util = __require("util")
local config = __require("config")

local M = { flyBody = nil, flying = false, noclipOn = false }

local original = { speed = nil, jump = nil }

function M.root()
	return env.Root()
end

--------------------------------------------------------------------------------
-- speed / jump
--------------------------------------------------------------------------------

function M.setSpeed(value)
	local humanoid = env.Humanoid()
	if not humanoid then return false end
	original.speed = original.speed or humanoid.WalkSpeed
	humanoid.WalkSpeed = value
	return true
end

function M.setJump(value)
	local humanoid = env.Humanoid()
	if not humanoid then return false end
	original.jump = original.jump or humanoid.JumpPower
	humanoid.UseJumpPower = true
	humanoid.JumpPower = value
	return true
end

function M.resetPhysics()
	local humanoid = env.Humanoid()
	if not humanoid then return end
	humanoid.WalkSpeed = original.speed or 16
	humanoid.JumpPower = original.jump or 50
	humanoid.UseJumpPower = true
end

--------------------------------------------------------------------------------
-- teleport
--------------------------------------------------------------------------------

function M.tweenTo(position, speed)
	local root = env.Root()
	if not root then return false end

	local stealth = __require("stealth")
	local allowed, witness = stealth.teleportAllowed(position)
	if not allowed then
		env.log("teleport held: %s is within range of the destination", tostring(witness))
		return false
	end

	speed = speed or config.get("tpSpeed")
	local distance = (root.Position - position).Magnitude
	local duration = util.clamp(distance / math.max(speed, 1), 0.08, 3)
	local tween = env.TweenService:Create(root, TweenInfo.new(duration, Enum.EasingStyle.Linear), { CFrame = CFrame.new(position) })
	tween:Play()

	if config.get("noclip") then
		pcall(function() root.CanCollide = false end)
	end
	tween.Completed:Wait()
	return true
end

function M.blink(position)
	local root = env.Root()
	if not root then return false end
	root.CFrame = CFrame.new(position)
	return true
end

--------------------------------------------------------------------------------
-- fly
--------------------------------------------------------------------------------

function M.stopFly()
	M.flying = false
	if M.flyBody then
		pcall(function() M.flyBody:Destroy() end)
		M.flyBody = nil
	end
	local root = env.Root()
	if root then
		for _, child in ipairs(root:GetChildren()) do
			if child:IsA("BodyVelocity") and child.Name == "FischHubFly" then child:Destroy() end
		end
	end
end

function M.startFly(speed)
	local root = env.Root()
	if not root then return false end
	M.stopFly()

	local body = Instance.new("BodyVelocity")
	body.Name = "FischHubFly"
	body.Velocity = Vector3.zero
	body.MaxForce = Vector3.new(1e6, 1e6, 1e6)
	body.P = 1250
	body.Parent = root
	M.flyBody = body
	M.flying = true
	M.flySpeed = speed or 80

	local humanoid = env.Humanoid()
	if humanoid then humanoid.PlatformStand = true end
	return true
end

local function flyStep()
	if not M.flying or not M.flyBody then return end
	local root = env.Root()
	local camera = workspace.CurrentCamera
	if not root or not camera then return end

	local move = Vector3.zero
	if env.UserInputService:IsKeyDown(Enum.KeyCode.W) then move += camera.CFrame.LookVector end
	if env.UserInputService:IsKeyDown(Enum.KeyCode.S) then move -= camera.CFrame.LookVector end
	if env.UserInputService:IsKeyDown(Enum.KeyCode.D) then move += camera.CFrame.RightVector end
	if env.UserInputService:IsKeyDown(Enum.KeyCode.A) then move -= camera.CFrame.RightVector end
	if env.UserInputService:IsKeyDown(Enum.KeyCode.Space) then move += Vector3.new(0, 1, 0) end
	if env.UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then move -= Vector3.new(0, 1, 0) end

	if move.Magnitude > 0 then
		M.flyBody.Velocity = move.Unit * M.flySpeed
	else
		M.flyBody.Velocity = Vector3.zero
	end
end

--------------------------------------------------------------------------------
-- noclip
--------------------------------------------------------------------------------

local function noclipStep()
	if not config.get("noclip") then return end
	local character = env.LocalPlayer.Character
	if not character then return end
	for _, part in ipairs(character:GetDescendants()) do
		if part:IsA("BasePart") and part.CanCollide then
			part.CanCollide = false
		end
	end
end

function M.setNoclip(enabled)
	config.set("noclip", enabled)
	if not enabled then
		local character = env.LocalPlayer.Character
		if character then
			for _, part in ipairs(character:GetDescendants()) do
				if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
					part.CanCollide = true
				end
			end
		end
	end
end

--------------------------------------------------------------------------------
-- oxygen
--
-- Fisch tracks air while submerged. The value lives either as a leaderstats
-- entry, a player attribute, or a field inside the character's humanoid
-- attributes depending on the version. All three are written every tick; a
-- write that lands on the wrong one is harmless.
--------------------------------------------------------------------------------

local function oxygenStep()
	if not config.get("infOxygen") then return end
	local player = env.LocalPlayer

	for _, container in ipairs({ player, player:FindFirstChild("leaderstats"), env.LocalPlayer.Character }) do
		if container then
			for _, child in ipairs(container:GetChildren()) do
				if child:IsA("IntValue") or child:IsA("NumberValue") then
					if util.matches(child.Name, config.patterns.oxygen) then
						child.Value = 100
					end
				end
			end
		end
	end

	for name in pairs(player:GetAttributes()) do
		if util.matches(name, config.patterns.oxygen) then
			pcall(function() player:SetAttribute(name, 100) end)
		end
	end
end

--------------------------------------------------------------------------------
-- tick
--------------------------------------------------------------------------------

util.task("motion", 0.1, function()
	pcall(flyStep)
	pcall(noclipStep)
	pcall(oxygenStep)
end)

return M

end)()

__modules["minigame"] = (function()
-- minigame: geometry classifier + predictive reel solver
--
-- Four reel shapes cover essentially every fishing game:
--   linear   - static zone, marker slides along the track
--   reverse  - static marker, zone slides along the track
--   fill     - a bar grows toward a marked target
--   radial   - marker orbits a centre point
-- plus `spam`, the fallback when the UI cannot be classified.
--
-- Every frame the marker's velocity is estimated from the last two samples and
-- the press is aimed at where it *will* be after the input latency, not where
-- it is now. That single change is what separates a solver from a spammer.
local env = __require("env")
local util = __require("util")
local config = __require("config")

local M = {
	active = false,
	gui = nil,
	track = nil,
	marker = nil,
	zone = nil,
	geometry = "none",
	lastPositions = setmetatable({}, { __mode = "k" }),
	velocity = Vector2(0, 0),
	lastSample = 0,
	samples = 0,
	hits = 0,
	misses = 0,
	lead = 0.08,
	tolerance = 0.12,
}

local function visible(obj)
	return obj
		and obj:IsA("GuiObject")
		and obj.Visible
		and obj.AbsoluteSize.X > 1
		and obj.AbsoluteSize.Y > 1
end

local function area(obj)
	return obj.AbsoluteSize.X * obj.AbsoluteSize.Y
end

local function centre(obj)
	return obj.AbsolutePosition + obj.AbsoluteSize / 2
end

local function horizontal(track)
	return track.AbsoluteSize.X >= track.AbsoluteSize.Y
end

--------------------------------------------------------------------------------
-- detection
--------------------------------------------------------------------------------

function M.findGui()
	local playerGui = env.LocalPlayer:FindFirstChildOfClass("PlayerGui")
	if not playerGui then return nil end

	local best, bestArea = nil, 0
	for _, gui in ipairs(playerGui:GetChildren()) do
		if gui:IsA("ScreenGui") and gui.Enabled and util.matches(gui.Name, config.patterns.minigame) then
			for _, child in ipairs(gui:GetDescendants()) do
				if visible(child) and area(child) > 4000 then
					if area(child) > bestArea then
						best, bestArea = gui, area(child)
					end
					break
				end
			end
		end
	end
	return best
end

local function pickTrack(gui)
	local track, trackArea = nil, 0
	for _, child in ipairs(gui:GetDescendants()) do
		if visible(child) and area(child) > trackArea then
			track, trackArea = child, area(child)
		end
	end
	if track and trackArea >= 4000 then return track end
	return nil
end

--------------------------------------------------------------------------------
-- classification
--------------------------------------------------------------------------------

local function classify(track, mover, still)
	if not mover then return "unknown" end

	local trackCentre = centre(track)
	local moverCentre = centre(mover)
	local offset = moverCentre - trackCentre
	local radius = offset.Magnitude
	local axis = horizontal(track) and "x" or "y"

	-- Orbiting marker: constant distance from the track centre while the angle
	-- keeps changing.
	local previousAngle = M.lastAngle
	local angle = math.atan2(offset.Y, offset.X)
	M.lastAngle = angle
	if previousAngle and radius > 10 then
		local delta = math.abs(angle - previousAngle)
		if delta > 1e-3 and delta < 1 then
			local previousRadius = M.lastRadius or radius
			if math.abs(radius - previousRadius) < radius * 0.25 then
				M.lastRadius = radius
				return "radial"
			end
		end
	end
	M.lastRadius = radius

	if not still then return "unknown" end

	-- Fill bar: the mover is a child whose Size changes while its Position is
	-- pinned to one edge of the track.
	local sizeChange = M.lastSize and (mover.AbsoluteSize - M.lastSize).Magnitude or 0
	M.lastSize = mover.AbsoluteSize
	if sizeChange > 0.5 then return "fill" end

	local stillCentre = centre(still)
	if still == mover then return "unknown" end

	-- Which one actually travels along the long axis?
	local function travel(obj)
		local previous = M.lastPositions[obj]
		if not previous then return 0 end
		local current = obj.AbsolutePosition
		local delta = current - previous
		return math.abs(axis == "x" and delta.X or delta.Y)
	end

	local moverTravel = travel(mover)
	local stillTravel = travel(still)

	if stillTravel > moverTravel * 1.5 then
		M.swap = true
		return "reverse"
	end

	if moverTravel > 0.05 then
		M.swap = false
		return "linear"
	end

	return "unknown"
end

function M.analyze(gui)
	local track = pickTrack(gui)
	if not track then
		M.geometry = "none"
		return false
	end
	M.track = track

	local movers, stills = {}, {}

	for _, child in ipairs(track:GetDescendants()) do
		if visible(child) and child ~= track then
			local previous = M.lastPositions[child]
			local current = child.AbsolutePosition
			if previous then
				local delta = (current - previous).Magnitude
				if delta > 0.4 then
					movers[#movers + 1] = { object = child, delta = delta }
				elseif area(child) < area(track) * 0.9 then
					stills[#stills + 1] = { object = child, area = area(child) }
				end
			end
			M.lastPositions[child] = current
		end
	end

	table.sort(movers, function(a, b) return a.delta > b.delta end)
	table.sort(stills, function(a, b) return a.area > b.area end)

	local mover = movers[1] and movers[1].object
	local still = stills[1] and stills[1].object

	if mover then
		local previous = M.lastPosition or centre(mover)
		local now = centre(mover)
		local deltaTime = math.max(util.now() - (M.lastSample or util.now()), 0.001)
		local instant = (now - previous) / deltaTime
		M.velocity = M.velocity * 0.6 + instant * 0.4
		M.lastPosition = now
		M.lastSample = util.now()
	end

	M.marker = mover
	M.zone = still

	if mover then
		M.geometry = classify(track, mover, still)
	else
		M.geometry = "unknown"
	end

	M.samples = M.samples + 1
	return M.geometry ~= "none"
end

--------------------------------------------------------------------------------
-- press helpers
--------------------------------------------------------------------------------

local function pressDown()
	if env.has.mouse1 then
		pcall(mouse1press)
	else
		pcall(function() env.VirtualInputManager:SendMouseButtonEvent(0, 0, 0, true, game, 0) end)
	end
end

local function pressUp()
	if env.has.mouse1 then
		pcall(mouse1release)
	else
		pcall(function() env.VirtualInputManager:SendMouseButtonEvent(0, 0, 0, false, game, 0) end)
	end
end

local function hold(duration)
	pressDown()
	task.wait(duration)
	pressUp()
end

--------------------------------------------------------------------------------
-- solving
--------------------------------------------------------------------------------

local function fraction(position, track, alongX)
	if alongX then
		return (position.X - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1)
	end
	return (position.Y - track.AbsolutePosition.Y) / math.max(track.AbsoluteSize.Y, 1)
end

local function solveLinear()
	local track, marker, zone = M.track, M.marker, M.zone
	if not (track and marker and zone) then return false end

	local alongX = horizontal(track)
	local predicted = centre(marker) + M.velocity * M.lead

	local low, high
	if M.swap then
		local zoneCentre = centre(zone)
		local half = (alongX and marker.AbsoluteSize.X or marker.AbsoluteSize.Y) / 2
		local value = alongX and zoneCentre.X or zoneCentre.Y
		low, high = value - half, value + half
	else
		local zoneStart = alongX and zone.AbsolutePosition.X or zone.AbsolutePosition.Y
		local zoneSize = alongX and zone.AbsoluteSize.X or zone.AbsoluteSize.Y
		low, high = zoneStart, zoneStart + zoneSize
	end

	local point = alongX and predicted.X or predicted.Y
	return point >= low and point <= high
end

local function solveFill()
	local marker = M.marker
	local track = M.track
	if not (marker and track) then return false end
	local ratio = marker.AbsoluteSize.Magnitude / math.max(track.AbsoluteSize.Magnitude, 1)
	return ratio >= 0.45 and ratio <= 0.95
end

local function solveRadial()
	local track, marker, zone = M.track, M.marker, M.zone
	if not (track and marker) then return false end

	local trackCentre = centre(track)
	local offset = centre(marker) - trackCentre
	local angle = math.atan2(offset.Y, offset.X)

	local target = M.lastTargetAngle
	if zone then
		local zoneOffset = centre(zone) - trackCentre
		target = math.atan2(zoneOffset.Y, zoneOffset.X)
		M.lastTargetAngle = target
	end
	if not target then return false end

	local delta = math.abs(((angle - target + math.pi) % (2 * math.pi)) - math.pi)
	return delta < M.tolerance * math.pi
end

function M.inWindow()
	local geometry = M.geometry
	if geometry == "linear" or geometry == "reverse" then
		return solveLinear()
	elseif geometry == "fill" then
		return solveFill()
	elseif geometry == "radial" then
		return solveRadial()
	end
	return false
end

--------------------------------------------------------------------------------
-- tick
--------------------------------------------------------------------------------

function M.tick(solve)
	local gui = M.findGui()
	if not gui then
		M.active = false
		M.gui = nil
		M.track, M.marker, M.zone = nil, nil, nil
		M.geometry = "none"
		M.samples = 0
		M.velocity = Vector2(0, 0)
		M.lastPosition = nil
		return false
	end

	if gui ~= M.gui then
		M.gui = gui
		M.samples = 0
		M.lastPositions = setmetatable({}, { __mode = "k" })
		M.lastPosition, M.lastSample = nil, nil
		M.velocity = Vector2(0, 0)
		M.analyze(gui)
	end

	M.active = true
	if solve == false then return true end

	if M.samples < 45 then
		M.analyze(gui)
	end

	local mode = config.get("reelMode")
	if mode == "Remote" then
		local remote = __require("scanner").remotes.reel
		if remote then
			pcall(function() remote:FireServer() end)
			M.hits = M.hits + 1
			return true
		end
	end

	if config.get("instantReel") == false then
		hold(0.05)
		task.wait(0.02)
		M.hits = M.hits + 1
		return true
	end

	if M.geometry == "none" or M.geometry == "unknown" then
		hold(0.05)
		task.wait(0.02)
		M.hits = M.hits + 1
		return true
	end

	-- Input frequency is itself a fingerprint. A real player does not press on
	-- every single frame; a short, random dead beat removes that regularity.
	if math.random() < 0.06 then
		task.wait(0.012 + math.random() * 0.03)
		return true
	end

	if M.inWindow() then
		hold(0.05 + math.random() * 0.025)
		M.hits = M.hits + 1
	else
		hold(0.012 + math.random() * 0.01)
	end
	return true
end

function M.status()
	return string.format("%s %s m%d z%d", M.geometry, M.active and "on" or "off",
		M.marker and 1 or 0, M.zone and 1 or 0)
end

function M.confidence()
	local known = { linear = 0.9, reverse = 0.9, fill = 0.8, radial = 0.7, unknown = 0.35, none = 0.1 }
	return known[M.geometry] or 0.35
end

return M

end)()

__modules["fishing"] = (function()
-- fishing: cast / wait / reel state machine
local env = __require("env")
local util = __require("util")
local config = __require("config")
local scanner = __require("scanner")
local minigame = __require("minigame")
local stealth = __require("stealth")

local M = {
	state = "idle",
	rod = nil,
	casts = 0,
	catches = 0,
	sessionStart = util.now(),
	lastCast = 0,
	waitStart = 0,
	waits = {},
	enabled = true,
}

local MAX_REEL_SECONDS = 25

local function equip(rod)
	local character = env.LocalPlayer.Character
	if not character then return false end
	if rod.Parent == character then return true end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then return false end
	local ok = pcall(function() humanoid:EquipTool(rod) end)
	task.wait(0.12)
	return ok and rod.Parent == character
end

function M.currentRod()
	if not config.get("autoRod") then
		local character = env.LocalPlayer.Character
		if character then
			for _, item in ipairs(character:GetChildren()) do
				if item:IsA("Tool") and util.matches(item.Name, config.patterns.rod) then
					return item
				end
			end
		end
		return nil
	end
	return scanner.bestRod()
end

local function cast()
	local rod = M.rod
	if not rod then
		M.state = "no-rod"
		return false
	end
	if not equip(rod) then
		M.state = "equip-failed"
		return false
	end

	if config.get("reelMode") == "Remote" then
		local remote = scanner.remotes.cast
		if remote then
			pcall(function() remote:FireServer() end)
			M.casts = M.casts + 1
			M.lastCast = util.now()
			M.state = "wait"
			M.waitStart = util.now()
			return true
		end
	end

	pcall(function() rod:Activate() end)
	M.casts = M.casts + 1
	M.lastCast = util.now()
	M.state = "wait"
	M.waitStart = util.now()
	return true
end

function M.step()
	if not M.enabled then
		M.state = "disabled"
		return
	end

	local wantCast = config.get("autoCast")
	local wantReel = config.get("autoReel")
	if not (wantCast or wantReel) then
		M.state = "off"
		return
	end

	-- A reel already in progress is always finished: abandoning mid-catch is
	-- exactly the kind of half-action that looks wrong. Everything else waits.
	if M.state ~= "reel" and stealth.blocked() then
		M.state = "hold:" .. (stealth.blockedReason or "?")
		return
	end

	local rod = M.currentRod()
	if not rod then
		M.state = "no-rod"
		return
	end
	M.rod = rod

	local active = minigame.tick(wantReel) == true

	if active then
		if wantReel then
			if M.state ~= "reel" then
				M.state = "reel"
				M.reelStart = util.now()
				M.wasReeling = true
				M.slip = stealth.shouldSlip()

				-- close out the wait sample so patience adapts to this rod
				if M.waitStart and M.waitStart > 0 then
					M.waits[#M.waits + 1] = util.now() - M.waitStart
					if #M.waits > 12 then table.remove(M.waits, 1) end
				end
			end

			if util.now() - (M.reelStart or 0) > MAX_REEL_SECONDS then
				M.state = "reel-timeout"
				M.reelStart = util.now()
			end

			-- Deliberate slip: hold off long enough that this catch escapes.
			-- A sub-perfect success rate is part of the profile, not a bug.
			if M.slip then
				if util.now() - M.reelStart < 0.65 then
					return
				end
				M.slip = false
			end
			return
		end
		M.state = "reel-skip"
		return
	end

	if M.wasReeling then
		M.wasReeling = false
		M.catches = M.catches + 1
		stealth.noteCatch()
		M.state = "loot"
		return
	end

	if not wantCast then
		M.state = "idle"
		return
	end

	local waited = util.now() - M.waitStart
	local average = 4
	if #M.waits > 0 then
		local total = 0
		for _, value in ipairs(M.waits) do total += value end
		average = total / #M.waits
	end
	local patience = util.clamp(math.max(average * 2.2, config.get("castDelay") + 1), 3, 20)
	patience = stealth.jitter(patience, 0.3)

	if M.state == "wait" and waited < patience then
		return
	end

	cast()
end

function M.stats()
	local elapsed = math.max(util.now() - M.sessionStart, 1)
	return {
		state = M.state,
		casts = M.casts,
		catches = M.catches,
		perMinute = M.catches / (elapsed / 60),
		rod = M.rod and M.rod.Name or nil,
	}
end

util.task("fishing", 0.05, function() pcall(M.step) end)

return M

end)()

__modules["economy"] = (function()
-- economy: sell, appraise, restock
--
-- Three interaction mechanisms are attempted in order, because the vendor
-- interface is the least stable part of a fishing game across updates:
--   1. ProximityPrompt  (hold / fire)
--   2. ClickDetector    (fireclickdetector)
--   3. RemoteEvent      (FireServer, discovered or learned)
local env = __require("env")
local util = __require("util")
local config = __require("config")
local scanner = __require("scanner")
local motion = __require("motion")

local M = { sells = 0, appraisals = 0, mechanism = "-" }

local function travel(position)
	local root = env.Root()
	if not (position and root) then return false end
	if (position - root.Position).Magnitude > 12 then
		return motion.tweenTo(position + Vector3.new(0, 3, 0))
	end
	return false
end

local function returnTo(origin)
	if origin then
		task.wait(0.2)
		pcall(motion.tweenTo, origin)
	end
end

local function firePrompt(prompt, times)
	if not prompt then return false end
	for _ = 1, times or 3 do
		if env.has.proximity then
			pcall(fireproximityprompt, prompt)
		else
			pcall(function()
				prompt:InputHoldBegin()
				task.wait(math.max(prompt.HoldDuration, 0.1))
				prompt:InputHoldEnd()
			end)
		end
		task.wait(0.22)
	end
	return true
end

local function fireDetector(detector)
	if typeof(fireclickdetector) ~= "function" then return false end
	local ok = pcall(fireclickdetector, detector)
	if ok then
		task.wait(0.25)
		pcall(fireclickdetector, detector)
	end
	return ok
end

local function fireRemote(remote)
	if not remote then return false end
	local ok = pcall(function() remote:FireServer() end)
	if not ok then
		ok = pcall(function() remote:InvokeServer() end)
	end
	return ok
end

function M.interact(kind, times)
	local origin = env.Root() and env.Root().Position

	-- 1. proximity prompt
	local record = scanner.nearestPrompt(kind)
	if record then
		travel(record.position)
		firePrompt(record.prompt, times)
		returnTo(origin)
		M.mechanism = "prompt"
		return true
	end

	-- 2. click detector
	local detectors = scanner.clickDetectors[kind]
	if detectors and #detectors > 0 then
		local best = detectors[1]
		travel(best.position)
		if fireDetector(best.detector) then
			returnTo(origin)
			M.mechanism = "clickdetector"
			return true
		end
	end

	-- 3. remote
	local remote = scanner.remotes[kind]
	if remote and fireRemote(remote) then
		M.mechanism = "remote"
		return true
	end

	M.mechanism = "none"
	return false
end

function M.sell()
	if not M.interact("sell", 4) then return false end
	M.sells = M.sells + 1
	return true
end

function M.appraise()
	if not M.interact("appraise", 2) then return false end
	M.appraisals = M.appraisals + 1
	return true
end

function M.buyBait()
	return M.interact("bait", 2)
end

local nextSell, nextAppraise = 0, 0

util.task("economy", 2, function()
	local now = util.now()

	if config.get("autoSell") then
		if nextSell == 0 then nextSell = now + 15 end
		if now >= nextSell then
			nextSell = M.sell() and (now + config.get("sellInterval")) or (now + 30)
		end
	else
		nextSell = 0
	end

	if config.get("autoAppraise") then
		if nextAppraise == 0 then nextAppraise = now + 30 end
		if now >= nextAppraise then
			M.appraise()
			nextAppraise = now + config.get("appraiseInterval")
		end
	else
		nextAppraise = 0
	end
end)

return M

end)()

__modules["quests"] = (function()
-- quests: turn-in and reward prompts
local env = __require("env")
local util = __require("util")
local config = __require("config")
local scanner = __require("scanner")
local motion = __require("motion")

local M = { claims = 0, lastClaim = 0 }

-- Quest NPCs are interacted with through ProximityPrompt, which is the one
-- interface every quest system in this genre exposes. Firing it repeatedly
-- covers the common pattern of talk -> accept -> hand in -> claim, since each
-- step is a fresh prompt on the same object.
function M.claim()
	local record = scanner.nearestPrompt("quest")
	if not record then return false end

	local origin = env.Root() and env.Root().Position
	if record.position and origin and (record.position - origin).Magnitude > 12 then
		motion.tweenTo(record.position + Vector3.new(0, 3, 0))
		task.wait(0.4)
	end

	for _ = 1, 6 do
		if env.has.proximity then
			pcall(fireproximityprompt, record.prompt)
		else
			pcall(function()
				record.prompt:InputHoldBegin()
				task.wait(math.max(record.prompt.HoldDuration, 0.1))
				record.prompt:InputHoldEnd()
			end)
		end
		task.wait(0.45)
	end

	if record.position and origin and (record.position - origin).Magnitude > 12 then
		motion.tweenTo(origin)
	end

	M.claims = M.claims + 1
	M.lastClaim = util.now()
	return true
end

local nextClaim = 0

util.task("quests", 4, function()
	if not config.get("autoQuest") then
		nextClaim = 0
		return
	end
	local now = util.now()
	if nextClaim == 0 then nextClaim = now + 20 end
	if now >= nextClaim then
		if M.claim() then
			nextClaim = now + config.get("questInterval")
		else
			nextClaim = now + 60
		end
	end
end)

return M

end)()

__modules["esp"] = (function()
-- esp: drawing-based overlay for players, fish, npcs, chests
local env = __require("env")
local util = __require("util")
local config = __require("config")

local M = {
	entries = {},
	candidates = {},
	refreshAt = 0,
	enabledColors = {
		player = Color3.fromRGB(88, 166, 255),
		fish = Color3.fromRGB(88, 214, 141),
		npc = Color3.fromRGB(240, 190, 90),
		chest = Color3.fromRGB(230, 120, 230),
	},
}

local function remove(entry)
	if entry.box then pcall(function() entry.box:Remove() end) end
	if entry.label then pcall(function() entry.label:Remove() end) end
end

function M.clear()
	for _, entry in pairs(M.entries) do remove(entry) end
	M.entries = {}
	M.candidates = {}
end

local function worldToScreen(position)
	local camera = workspace.CurrentCamera
	if not camera then return nil, 0 end
	local screen, onScreen = camera:WorldToViewportPoint(position)
	if not onScreen or screen.Z <= 0 then return nil, screen.Z end
	return Vector2.new(screen.X, screen.Y), screen.Z
end

local function classify(name)
	local patterns = config.patterns
	if util.matches(name, patterns.espFish) then return "fish" end
	if util.matches(name, patterns.espNpc) then return "npc" end
	return "fish"
end

local function rebuildCandidates()
	local camera = workspace.CurrentCamera
	if not camera then return end
	local origin = camera.CFrame.Position
	local range = config.get("espRange")
	local list = {}

	if config.get("espPlayers") then
		for _, player in ipairs(env.Players:GetPlayers()) do
			if player ~= env.LocalPlayer and player.Character then
				local head = player.Character:FindFirstChild("Head")
				local root = player.Character:FindFirstChild("HumanoidRootPart")
				if root then
					list[#list + 1] = { kind = "player", position = root.Position, name = player.Name, object = player.Character }
				elseif head then
					list[#list + 1] = { kind = "player", position = head.Position, name = player.Name, object = player.Character }
				end
			end
		end
	end

	local wantFish = config.get("espFish")
	local wantNpc = config.get("espNpcs")
	local wantChest = config.get("espChests")

	if wantFish or wantNpc or wantChest then
		for _, part in ipairs(workspace:GetDescendants()) do
			if part:IsA("BasePart") and part.Parent then
				local kind
				local name = part.Name
				if wantNpc and util.matches(name, config.patterns.espNpc) then
					kind = "npc"
				elseif wantChest and (util.matches(name, { "chest", "crate", "loot" })) then
					kind = "chest"
				elseif wantFish and util.matches(name, config.patterns.espFish) then
					kind = "fish"
				end
				if kind then
					local distance = (part.Position - origin).Magnitude
					if distance <= range then
						list[#list + 1] = { kind = kind, position = part.Position, name = name, object = part, distance = distance }
					end
				end
			end
		end
	end

	M.candidates = list
end

local function ensure(entry)
	if entry.box or entry.label then return end
	if config.get("espBoxes") then
		local box = Drawing.new("Square")
		box.Thickness = 1
		box.Filled = false
		box.Transparency = 0.85
		box.Color = M.enabledColors[entry.kind] or Color3.new(1, 1, 1)
		entry.box = box
	end
	if config.get("espLabels") then
		local label = Drawing.new("Text")
		label.Size = 13
		label.Center = true
		label.Outline = true
		label.Color = M.enabledColors[entry.kind] or Color3.new(1, 1, 1)
		entry.label = label
	end
end

function M.step()
	if not env.has.drawing then return end
	if not config.get("esp") then
		if next(M.entries) then M.clear() end
		return
	end

	local now = util.now()
	if now >= M.refreshAt then
		M.refreshAt = now + 1
		rebuildCandidates()
	end

	local seen = {}
	for index, candidate in ipairs(M.candidates) do
		local key = candidate.object or index
		seen[key] = true
		local screen, depth = worldToScreen(candidate.position)

		if screen then
			local entry = M.entries[key]
			if not entry then
				entry = { kind = candidate.kind, name = candidate.name }
				M.entries[key] = entry
			end
			ensure(entry)

			local scale = util.clamp(1600 / math.max(depth, 1), 10, 180)
			if entry.box then
				entry.box.Size = Vector2.new(scale, scale)
				entry.box.Position = screen - Vector2.new(scale / 2, scale / 2)
				entry.box.Visible = true
			end
			if entry.label then
				local text = candidate.kind == "player" and candidate.name
					or string.format("%s [%dm]", candidate.name, math.floor(depth))
				entry.label.Text = text
				entry.label.Position = screen - Vector2.new(0, scale / 2 + 16)
				entry.label.Visible = true
			end
		else
			local entry = M.entries[key]
			if entry then
				if entry.box then entry.box.Visible = false end
				if entry.label then entry.label.Visible = false end
			end
		end
	end

	for key, entry in pairs(M.entries) do
		if not seen[key] then
			remove(entry)
			M.entries[key] = nil
		end
	end
end

util.task("esp", 0.1, function() pcall(M.step) end)

return M

end)()

__modules["anti"] = (function()
-- anti: anti-afk, staff detection, auto rejoin, performance cleanup
local env = __require("env")
local util = __require("util")
local config = __require("config")

local M = {
	staff = {},
	staffPresent = false,
	paused = false,
	kicks = 0,
	rejoins = 0,
	lastRejoin = 0,
}

-- Names and group ids checked for staff. Add to this from the console with
-- getgenv().FischHub.anti.watch("name", "groupid")
M.watchList = {}
M.watchGroups = {}

function M.watch(name, groupId)
	M.watchList[name:lower()] = true
	if groupId then M.watchGroups[tostring(groupId)] = true end
end

local function looksLikeStaff(player)
	local name = player.Name:lower()
	local display = (player.DisplayName or ""):lower()

	if M.watchList[name] or M.watchList[display] then return true end
	for marker in pairs({ mod = true, admin = true, staff = true, dev = true }) do
		if name:find(marker, 1, true) or display:find(marker, 1, true) then return true end
	end

	for groupId in pairs(M.watchGroups) do
		local ok, rank = pcall(function() return player:GetRankInGroup(tonumber(groupId) or 0) end)
		if ok and rank and rank >= 250 then return true end
	end
	return false
end

function M.scanStaff()
	local found = {}
	for _, player in ipairs(env.Players:GetPlayers()) do
		if player ~= env.LocalPlayer and looksLikeStaff(player) then
			found[player.Name] = true
		end
	end
	local changed = false
	for name in pairs(found) do
		if not M.staff[name] then changed = true end
	end
	for name in pairs(M.staff) do
		if not found[name] then changed = true end
	end
	M.staff = found
	M.staffPresent = next(found) ~= nil
	if changed and config.get("notify") then
		local names = {}
		for name in pairs(found) do names[#names + 1] = name end
		table.sort(names)
		if M.staffPresent then
			env.log("staff detected: %s", table.concat(names, ", "))
		end
	end
	return M.staffPresent
end

local function antiAfk()
	local humanoid = env.Humanoid()
	if not humanoid then return end
	pcall(function()
		env.VirtualUser:CaptureController()
		env.VirtualUser:ClickButton2(Vector2.new())
	end)
	if humanoid.MoveDirection.Magnitude < 0.01 then
		humanoid.Jump = true
	end
end

function M.shouldPause()
	return config.get("antiMod") and M.staffPresent
end

function M.rejoin()
	if not env.has.queue then return false end
	if util.now() - M.lastRejoin < 30 then return false end
	M.lastRejoin = util.now()
	M.rejoins = M.rejoins + 1
	local placeId = game.PlaceId
	local jobId = game.JobId
	-- No queue_on_teleport here on purpose: the hub is reloaded by the executor
	-- autoexec stub on the next injection, so queueing a duplicate would run it
	-- twice. install.sh keeps that stub in every detected executor folder.
	if jobId and jobId ~= "" then
		pcall(function()
			game:GetService("TeleportService"):TeleportToPlaceInstance(placeId, jobId, env.LocalPlayer)
		end)
	else
		pcall(function()
			game:GetService("TeleportService"):Teleport(placeId, env.LocalPlayer)
		end)
	end
	return true
end

local function hookDisconnect()
	local service = game:GetService("TeleportService")
	service.TeleportInitFailed:Connect(function()
		M.kicks = M.kicks + 1
		if config.get("autoRejoin") then
			task.delay(3, function() pcall(M.rejoin) end)
		end
	end)
end

function M.cleanupVisuals()
	local removed = 0
	for _, obj in ipairs(workspace:GetDescendants()) do
		if obj:IsA("ParticleEmitter") or obj:IsA("Smoke") or obj:IsA("Fire") or obj:IsA("Sparkles") then
			pcall(function() obj.Enabled = false end)
			removed = removed + 1
		end
	end
	env.Lighting.GlobalShadows = false
	return removed
end

hookDisconnect()

util.task("anti", 2, function()
	if config.get("antiMod") then M.scanStaff() end
end)

util.task("antiafk", 60, function()
	if config.get("antiAfk") then pcall(antiAfk) end
end)

return M

end)()

__modules["learn"] = (function()
-- learn: record the remotes the game actually uses
--
-- This is the module that closes the guess gap. Instead of hoping a remote is
-- named "Reel", the hub watches `__namecall` while you perform one action by
-- hand and records exactly which RemoteEvent fired, with what arguments and at
-- what rate. Press "Tag: reel" before reeling once, and the recorded remote is
-- the real one, by construction.
--
-- Hooking __namecall is deliberately isolated here: one connection, fully
-- pcall-guarded, removable, and inert until recording is switched on.
local env = __require("env")
local util = __require("util")
local config = __require("config")

local M = {
	recording = false,
	hooked = false,
	entries = {},
	counts = {},
	byTag = {},
	tag = nil,
	tagUntil = 0,
	good = false,
	MAX_ENTRIES = 400,
}

local originalNamecall = nil
local metatable = nil

--------------------------------------------------------------------------------
-- hook plumbing
--------------------------------------------------------------------------------

local function canHook()
	return typeof(getrawmetatable) == "function"
		and typeof(setreadonly) == "function"
		and typeof(getnamecallmethod) == "function"
end

local function describe(value)
	local kind = typeof(value)
	if kind == "Instance" then
		return string.format("%s(%s)", value.Name, value.ClassName)
	elseif kind == "string" then
		return string.format("%q", value:sub(1, 40))
	elseif kind == "number" or kind == "boolean" or kind == "nil" then
		return tostring(value)
	elseif kind == "Vector3" then
		return string.format("V3(%d,%d,%d)", value.X, value.Y, value.Z)
	elseif kind == "table" then
		return "table"
	end
	return kind
end

local function record(remote, method, args)
	if not M.recording then return end
	local name = remote:GetFullName()
	local now = util.now()

	local signatureParts = {}
	for index = 1, math.min(#args, 6) do
		signatureParts[#signatureParts + 1] = describe(args[index])
	end
	local signature = table.concat(signatureParts, ",")

	local entry = {
		name = name,
		remote = remote,
		method = method,
		time = now,
		argc = #args,
		signature = signature,
		tag = (M.tag and now <= M.tagUntil) and M.tag or nil,
	}

	M.entries[#M.entries + 1] = entry
	if #M.entries > M.MAX_ENTRIES then table.remove(M.entries, 1) end

	local stat = M.counts[name]
	if not stat then
		stat = { name = name, remote = remote, count = 0, first = now, last = now, tags = {}, signatures = {} }
		M.counts[name] = stat
	end
	stat.count = stat.count + 1
	stat.last = now
	stat.remote = remote
	if entry.tag then
		stat.tags[entry.tag] = (stat.tags[entry.tag] or 0) + 1
		M.byTag[entry.tag] = M.byTag[entry.tag] or {}
		M.byTag[entry.tag][name] = (M.byTag[entry.tag][name] or 0) + 1
	end
	if signature ~= "" then
		stat.signatures[signature] = (stat.signatures[signature] or 0) + 1
	end
	return entry
end

function M.hook()
	if M.hooked then return true end
	if not canHook() then
		env.log("executor cannot hook __namecall - learning disabled")
		return false
	end

	local ok, err = pcall(function()
		metatable = getrawmetatable(game)
		originalNamecall = metatable.__namecall
		setreadonly(metatable, false)

		metatable.__namecall = function(self, ...)
			local method = getnamecallmethod()
			if M.recording and (method == "FireServer" or method == "InvokeServer") then
				pcall(record, self, method, { ... })
			end
			return originalNamecall(self, ...)
		end

		setreadonly(metatable, true)
	end)

	if not ok then
		env.log("hook failed: %s", tostring(err))
		pcall(function() if metatable then setreadonly(metatable, true) end end)
		return false
	end

	M.hooked = true
	return true
end

function M.unhook()
	if not M.hooked or not metatable then return end
	pcall(function()
		setreadonly(metatable, false)
		metatable.__namecall = originalNamecall
		setreadonly(metatable, true)
	end)
	M.hooked = false
	M.recording = false
end

--------------------------------------------------------------------------------
-- session control
--------------------------------------------------------------------------------

function M.start()
	M.entries = {}
	M.counts = {}
	M.byTag = {}
	M.tag = nil
	M.recording = true
	return M.hook()
end

function M.stop()
	M.recording = false
	return #M.entries
end

function M.tagNext(label, seconds)
	M.tag = label
	M.tagUntil = util.now() + (seconds or 8)
	return true
end

--------------------------------------------------------------------------------
-- analysis
--------------------------------------------------------------------------------

function M.bestForTag(label)
	local bucket = M.byTag[label]
	if not bucket then return nil, 0 end

	local bestName, bestCount = nil, 0
	for name, count in pairs(bucket) do
		if count > bestCount then bestName, bestCount = name, count end
	end
	if not bestName then return nil, 0 end

	local stat = M.counts[bestName]
	return stat and stat.remote or nil, bestCount
end

-- A reel remote is fired many times per second; a cast or sell remote fires
-- once per action. Rate separates them without any naming convention.
function M.classify()
	local ranked = {}
	for _, stat in pairs(M.counts) do
		local span = math.max(stat.last - stat.first, 0.001)
		stat.rate = stat.count / span
		ranked[#ranked + 1] = stat
	end
	table.sort(ranked, function(a, b) return a.rate > b.rate end)

	local reel, cast
	for _, stat in ipairs(ranked) do
		if stat.count >= 4 and stat.rate >= 2 and not reel then
			reel = stat
		elseif stat.count >= 1 and stat.rate < 2 and not cast then
			cast = stat
		end
	end
	return ranked, reel, cast
end

function M.report()
	local ranked = M.classify()
	local lines = { string.format("%d remotes recorded", #ranked) }
	for index, stat in ipairs(ranked) do
		if index > 8 then break end
		lines[#lines + 1] = string.format("  %.2f/s  x%-4d %s", stat.rate, stat.count, stat.name)
	end
	return table.concat(lines, "\n")
end

function M.apply()
	local scanner = __require("scanner")
	local ranked, reel, cast = M.classify()
	local applied = {}

	local reelTag = M.bestForTag("reel")
	if reelTag then scanner.remotes.reel = reelTag; applied.reel = reelTag.Name end
	local castTag = M.bestForTag("cast")
	if castTag then scanner.remotes.cast = castTag; applied.cast = castTag.Name end
	local sellTag = M.bestForTag("sell")
	if sellTag then scanner.remotes.sell = sellTag; applied.sell = sellTag.Name end

	if not applied.reel and reel then
		scanner.remotes.reel = reel.remote
		applied.reel = reel.name
	end
	if not applied.cast and cast then
		scanner.remotes.cast = cast.remote
		applied.cast = cast.name
	end

	M.good = applied.reel ~= nil
	config.save()
	return applied
end

return M

end)()

__modules["ui"] = (function()
-- ui: tabbed panel
local env = __require("env")
local util = __require("util")
local config = __require("config")

local M = { root = nil, tabs = {}, pages = {}, current = nil, notifications = nil }

local Palette = {
	bg      = Color3.fromRGB(14, 15, 18),
	panel   = Color3.fromRGB(22, 23, 28),
	row     = Color3.fromRGB(32, 34, 41),
	rowOn   = Color3.fromRGB(30, 46, 38),
	accent  = Color3.fromRGB(90, 200, 160),
	good    = Color3.fromRGB(90, 220, 140),
	warn    = Color3.fromRGB(240, 170, 80),
	bad     = Color3.fromRGB(240, 110, 110),
	text    = Color3.fromRGB(232, 234, 240),
	dim     = Color3.fromRGB(138, 142, 155),
	border  = Color3.fromRGB(48, 50, 60),
}

local function inst(class, props, parent)
	local object = Instance.new(class)
	for key, value in pairs(props) do object[key] = value end
	if parent then object.Parent = parent end
	return object
end

local function round(parent, radius)
	inst("UICorner", { CornerRadius = UDim.new(0, radius or 6) }, parent)
end

local function pad(parent, amount)
	inst("UIPadding", {
		PaddingLeft = UDim.new(0, amount),
		PaddingRight = UDim.new(0, amount),
		PaddingTop = UDim.new(0, amount),
		PaddingBottom = UDim.new(0, amount),
	}, parent)
end

--------------------------------------------------------------------------------
-- notifications
--------------------------------------------------------------------------------

function M.notify(text, tone)
	if not M.notifications then return end
	local color = tone == "good" and Palette.good or tone == "bad" and Palette.bad or Palette.accent

	local frame = inst("Frame", {
		Size = UDim2.fromOffset(260, 32),
		BackgroundColor3 = Palette.panel,
		BackgroundTransparency = 0.08,
		BorderSizePixel = 0,
	}, M.notifications)
	round(frame, 6)
	inst("UIStroke", { Color = color, Thickness = 1, Transparency = 0.45 }, frame)

	local label = inst("TextLabel", {
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Text = text,
		TextColor3 = Palette.text,
		TextSize = 13,
		Font = Enum.Font.GothamMedium,
		TextXAlignment = Enum.TextXAlignment.Left,
	}, frame)
	inst("UIPadding", { PaddingLeft = UDim.new(0, 10) }, label)

	if config.get("notify") then
		task.delay(4.5, function()
			pcall(function()
				env.TweenService:Create(frame, TweenInfo.new(0.3), { BackgroundTransparency = 1 }):Play()
				task.wait(0.35)
				frame:Destroy()
			end)
		end)
	end
end

--------------------------------------------------------------------------------
-- row builders
--------------------------------------------------------------------------------

local function rowShell(parent, height)
	local row = inst("Frame", {
		Size = UDim2.new(1, -10, 0, height or 30),
		BackgroundColor3 = Palette.row,
		BorderSizePixel = 0,
	}, parent)
	round(row, 5)
	return row
end

local function toggleRow(parent, labelText, key, onChange)
	local row = rowShell(parent, 30)
	local dot = inst("Frame", {
		Size = UDim2.fromOffset(10, 10),
		Position = UDim2.new(1, -20, 0.5, -5),
		BackgroundColor3 = config.get(key) and Palette.good or Palette.dim,
		BorderSizePixel = 0,
	}, row)
	round(dot, 5)

	inst("TextLabel", {
		Size = UDim2.new(1, -44, 1, 0),
		Position = UDim2.fromOffset(10, 0),
		BackgroundTransparency = 1,
		Text = labelText,
		TextColor3 = Palette.text,
		TextSize = 13,
		Font = Enum.Font.GothamMedium,
		TextXAlignment = Enum.TextXAlignment.Left,
	}, row)

	local hit = inst("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "" }, row)

	local function flip()
		config.set(key, not config.get(key))
		dot.BackgroundColor3 = config.get(key) and Palette.good or Palette.dim
		row.BackgroundColor3 = config.get(key) and Palette.rowOn or Palette.row
		if onChange then onChange(config.get(key)) end
	end

	hit.MouseButton1Click:Connect(flip)
	return row, flip
end

local function sliderRow(parent, labelText, key, low, high, onChange)
	local row = inst("Frame", {
		Size = UDim2.new(1, -10, 0, 44),
		BackgroundColor3 = Palette.row,
		BorderSizePixel = 0,
	}, parent)
	round(row, 5)

	local text = inst("TextLabel", {
		Size = UDim2.new(1, -20, 0, 18),
		Position = UDim2.fromOffset(10, 4),
		BackgroundTransparency = 1,
		Text = string.format("%s  %s", labelText, tostring(config.get(key))),
		TextColor3 = Palette.text,
		TextSize = 12,
		Font = Enum.Font.GothamMedium,
		TextXAlignment = Enum.TextXAlignment.Left,
	}, row)

	local track = inst("Frame", {
		Size = UDim2.new(1, -20, 0, 4),
		Position = UDim2.fromOffset(10, 30),
		BackgroundColor3 = Palette.border,
		BorderSizePixel = 0,
	}, row)
	round(track, 2)

	local fill = inst("Frame", {
		Size = UDim2.fromScale((config.get(key) - low) / (high - low), 1),
		BackgroundColor3 = Palette.accent,
		BorderSizePixel = 0,
	}, track)

	local hit = inst("TextButton", { Size = UDim2.new(1, 0, 0, 22), Position = UDim2.fromOffset(0, 20), BackgroundTransparency = 1, Text = "" }, row)

	local function apply(absoluteX)
		local left = track.AbsolutePosition.X
		local width = track.AbsoluteSize.X
		local ratio = util.clamp((absoluteX - left) / math.max(width, 1), 0, 1)
		local value = low + (high - low) * ratio
		value = math.floor(value * 10 + 0.5) / 10
		fill.Size = UDim2.fromScale(ratio, 1)
		text.Text = string.format("%s  %s", labelText, tostring(value))
		config.set(key, value)
		if onChange then onChange(value) end
	end

	hit.MouseButton1Click:Connect(function() apply(env.UserInputService:GetMouseLocation().X) end)
	return row
end

local function buttonRow(parent, labelText, callback, height)
	local button = inst("TextButton", {
		Size = UDim2.new(1, -10, 0, height or 28),
		BackgroundColor3 = Palette.row,
		BorderSizePixel = 0,
		Text = labelText,
		TextColor3 = Palette.text,
		TextSize = 13,
		Font = Enum.Font.GothamMedium,
		AutoButtonColor = true,
	}, parent)
	round(button, 5)
	button.MouseButton1Click:Connect(function()
		local ok, err = pcall(callback)
		if not ok then M.notify(tostring(err), "bad") end
	end)
	return button
end

local function inputRow(parent, placeholder, callback)
	local box = inst("TextBox", {
		Size = UDim2.new(1, -10, 0, 28),
		BackgroundColor3 = Palette.row,
		BorderSizePixel = 0,
		Text = "",
		PlaceholderText = placeholder,
		PlaceholderColor3 = Palette.dim,
		TextColor3 = Palette.text,
		TextSize = 12,
		Font = Enum.Font.Gotham,
		ClearTextOnFocus = false,
	}, parent)
	round(box, 5)
	inst("UIPadding", { PaddingLeft = UDim.new(0, 10) }, box)
	box.FocusLost:Connect(function(enterPressed)
		if enterPressed and box.Text ~= "" then callback(box.Text) end
	end)
	return box
end

local function header(parent, text)
	return inst("TextLabel", {
		Size = UDim2.new(1, -10, 0, 18),
		BackgroundTransparency = 1,
		Text = text:upper(),
		TextColor3 = Palette.dim,
		TextSize = 10,
		Font = Enum.Font.GothamBold,
		TextXAlignment = Enum.TextXAlignment.Left,
	}, parent)
end

--------------------------------------------------------------------------------
-- page construction
--------------------------------------------------------------------------------

local function newPage()
	local scroll = inst("ScrollingFrame", {
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		ScrollBarThickness = 2,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		Visible = false,
	}, M.content)
	inst("UIListLayout", { Padding = UDim.new(0, 5), SortOrder = Enum.SortOrder.LayoutOrder }, scroll)
	pad(scroll, 10)
	return scroll
end

local function buildFishingPage()
	local page = newPage()
	header(page, "autofish")
	toggleRow(page, "Auto Cast", "autoCast")
	toggleRow(page, "Auto Reel", "autoReel")
	toggleRow(page, "Instant Reel", "instantReel")
	toggleRow(page, "Auto Rod (best in bag)", "autoRod")
	header(page, "timing")
	sliderRow(page, "Cast delay", "castDelay", 0.2, 3)
	buttonRow(page, "Reset session counters", function()
		local fishing = __require("fishing")
		fishing.casts, fishing.catches = 0, 0
		fishing.sessionStart = util.now()
		M.notify("counters reset", "good")
	end)
	return page
end

local function buildEconomyPage()
	local page = newPage()
	header(page, "automation")
	toggleRow(page, "Auto Sell", "autoSell")
	toggleRow(page, "Auto Appraise", "autoAppraise")
	toggleRow(page, "Auto Quest", "autoQuest")
	header(page, "intervals")
	sliderRow(page, "Sell every (s)", "sellInterval", 30, 600)
	sliderRow(page, "Appraise every (s)", "appraiseInterval", 60, 900)
	header(page, "manual")
	buttonRow(page, "Sell now", function()
		local ok = __require("economy").sell()
		M.notify(ok and "sell pass done" or "no vendor in range", ok and "good" or "bad")
	end)
	buttonRow(page, "Appraise now", function()
		local ok = __require("economy").appraise()
		M.notify(ok and "appraisal done" or "no appraiser in range", ok and "good" or "bad")
	end)
	return page
end

local function buildMovePage()
	local page = newPage()
	local motion = __require("motion")
	header(page, "movement")
	sliderRow(page, "Walk speed", "walkSpeed", 16, 200, function(value) motion.setSpeed(value) end)
	sliderRow(page, "Jump power", "jumpPower", 50, 300, function(value) motion.setJump(value) end)
	toggleRow(page, "Fly", "fly", function(value)
		if value then
			motion.startFly(80)
		else
			motion.stopFly()
		end
	end)
	toggleRow(page, "Noclip", "noclip", function(value) motion.setNoclip(value) end)
	toggleRow(page, "Infinite oxygen", "infOxygen")
	header(page, "teleport")
	inputRow(page, "landmark name, press enter", function(text)
		local scanner = __require("scanner")
		scanner.refresh(true)
		local target = scanner.landmark(text)
		if target then
			motion.tweenTo(target + Vector3.new(0, 5, 0))
			M.notify("tp -> " .. text, "good")
		else
			M.notify("no landmark: " .. text, "bad")
		end
	end)
	buttonRow(page, "Save waypoint", function()
		local scanner = __require("scanner")
		local root = env.Root()
		if root then
			scanner.landmarks["wp-" .. os.time()] = root.Position
			M.notify("waypoint saved", "good")
		end
	end)
	return page
end

local function buildEspPage()
	local page = newPage()
	header(page, "targets")
	toggleRow(page, "ESP master", "esp")
	toggleRow(page, "Players", "espPlayers")
	toggleRow(page, "Fish / items", "espFish")
	toggleRow(page, "NPCs", "espNpcs")
	toggleRow(page, "Chests", "espChests")
	header(page, "render")
	toggleRow(page, "Boxes", "espBoxes")
	toggleRow(page, "Labels", "espLabels")
	sliderRow(page, "Range (studs)", "espRange", 100, 2000)
	return page
end

local function buildStealthPage()
	local page = newPage()
	local stealth = __require("stealth")

	header(page, "profile")
	toggleRow(page, "Stealth master", "stealth")
	toggleRow(page, "Timing humanization", "humanize")
	header(page, "presence")
	toggleRow(page, "Hide when players can see you", "pauseOnPlayers")
	sliderRow(page, "Proximity radius (studs)", "proximityRadius", 40, 400)
	toggleRow(page, "Teleport guard", "teleportGuard")
	header(page, "pacing")
	sliderRow(page, "Catch cap (per minute)", "rateCap", 4, 30)
	sliderRow(page, "Imperfection", "imperfection", 0, 0.3)
	sliderRow(page, "Session length (min)", "sessionMinutes", 15, 180)
	sliderRow(page, "Break length (min)", "breakMinutes", 1, 30)
	header(page, "presets")
	buttonRow(page, "Apply paranoid preset", function()
		config.set("humanize", true)
		config.set("pauseOnPlayers", true)
		config.set("proximityRadius", 250)
		config.set("teleportGuard", true)
		config.set("rateCap", 9)
		config.set("imperfection", 0.12)
		config.set("sessionMinutes", 40)
		config.set("breakMinutes", 11)
		M.notify("paranoid preset applied", "good")
	end)
	buttonRow(page, "Apply normal preset", function()
		config.set("proximityRadius", 140)
		config.set("rateCap", 14)
		config.set("imperfection", 0.07)
		config.set("sessionMinutes", 55)
		config.set("breakMinutes", 7)
		M.notify("normal preset applied", "good")
	end)
	header(page, "emergency")
	buttonRow(page, "PANIC - disable everything now", function()
		stealth.engagePanic()
	end)
	buttonRow(page, "Release panic", function()
		stealth.releasePanic()
		M.notify("panic released - features stay off until re-enabled", "good")
	end)
	return page
end

local function buildMiscPage()
	local page = newPage()
	header(page, "safety")
	toggleRow(page, "Anti-AFK", "antiAfk")
	toggleRow(page, "Pause on staff", "antiMod")
	toggleRow(page, "Auto rejoin", "autoRejoin")
	buttonRow(page, "Add staff name (console)", function()
		M.notify("use getgenv().FischHub.anti.watch(name)", "good")
	end)
	header(page, "performance")
	buttonRow(page, "Strip particles", function()
		local removed = __require("anti").cleanupVisuals()
		M.notify(string.format("%d effects disabled", removed), "good")
	end)
	header(page, "diagnostics")
	buttonRow(page, "Probe remotes + prompts", function()
		local scanner = __require("scanner")
		scanner.refresh(true)
		env.log(scanner.summary())
		for _, remote in ipairs(scanner.remotes.all) do
			env.log("  remote %s", remote:GetFullName())
		end
		for kind, records in pairs(scanner.prompts) do
			for _, record in ipairs(records) do
				env.log("  prompt[%s] %s", kind, record.prompt:GetFullName())
			end
		end
		M.notify("probe written to console", "good")
	end)
	return page
end

local function buildLearnPage()
	local page = newPage()
	local learn = __require("learn")

	header(page, "remote capture")
	buttonRow(page, "Start capture", function()
		if learn.start() then
			M.notify("capturing - do one action by hand", "good")
		else
			M.notify("executor cannot hook namecall", "bad")
		end
	end)
	buttonRow(page, "Tag next as CAST", function()
		learn.tagNext("cast")
		M.notify("next remote tagged cast", "good")
	end)
	buttonRow(page, "Tag next as REEL", function()
		learn.tagNext("reel", 15)
		M.notify("next remotes tagged reel", "good")
	end)
	buttonRow(page, "Tag next as SELL", function()
		learn.tagNext("sell")
		M.notify("next remote tagged sell", "good")
	end)
	buttonRow(page, "Stop and apply", function()
		local count = learn.stop()
		local applied = learn.apply()
		local parts = {}
		for kind, name in pairs(applied) do parts[#parts + 1] = kind .. "=" .. name end
		M.notify(string.format("%d calls, %s", count, #parts > 0 and table.concat(parts, " ") or "nothing matched"),
			#parts > 0 and "good" or "bad")
	end)
	header(page, "results")
	buttonRow(page, "Dump capture to console", function()
		env.log(learn.report())
		M.notify("written to console", "good")
	end)
	buttonRow(page, "Unhook", function()
		learn.unhook()
		M.notify("unhooked", "good")
	end)
	return page
end

--------------------------------------------------------------------------------
-- shell
--------------------------------------------------------------------------------

local function tabButton(parent, text, index)
	local button = inst("TextButton", {
		Size = UDim2.fromOffset(84, 26),
		Position = UDim2.fromOffset(index * 88, 0),
		BackgroundColor3 = Palette.row,
		BorderSizePixel = 0,
		Text = text,
		TextColor3 = Palette.dim,
		TextSize = 11,
		Font = Enum.Font.GothamBold,
		LayoutOrder = index,
	}, parent)
	round(button, 4)
	return button
end

function M.select(name)
	for key, page in pairs(M.pages) do page.Visible = (key == name) end
	for key, button in pairs(M.tabs) do
		button.TextColor3 = (key == name) and Palette.accent or Palette.dim
		button.BackgroundColor3 = (key == name) and Palette.panel or Palette.row
	end
	M.current = name
end

function M.build()
	local gui = inst("ScreenGui", {
		Name = "FischHub",
		ResetOnSpawn = false,
		IgnoreGuiInset = true,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		DisplayOrder = 60,
	}, env.CoreGui)

	M.notifications = inst("Frame", {
		Size = UDim2.fromOffset(260, 220),
		Position = UDim2.new(1, -280, 0, 60),
		BackgroundTransparency = 1,
	}, gui)
	inst("UIListLayout", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }, M.notifications)

	local root = inst("Frame", {
		Size = UDim2.fromOffset(420, 430),
		Position = UDim2.new(0, 20, 0.5, -215),
		BackgroundColor3 = Palette.bg,
		BorderSizePixel = 0,
		ClipsDescendants = true,
	}, gui)
	M.root = root
	round(root, 8)
	inst("UIStroke", { Color = Palette.border, Thickness = 1 }, root)

	local bar = inst("Frame", {
		Size = UDim2.new(1, 0, 0, 32),
		BackgroundColor3 = Palette.panel,
		BorderSizePixel = 0,
	}, root)

	inst("TextLabel", {
		Size = UDim2.new(1, -90, 1, 0),
		Position = UDim2.fromOffset(12, 0),
		BackgroundTransparency = 1,
		Text = "FISCH HUB",
		TextColor3 = Palette.text,
		TextSize = 12,
		Font = Enum.Font.GothamBold,
		TextXAlignment = Enum.TextXAlignment.Left,
	}, bar)

	local close = inst("TextButton", {
		Size = UDim2.fromOffset(28, 32),
		Position = UDim2.new(1, -28, 0, 0),
		BackgroundTransparency = 1,
		Text = "x",
		TextColor3 = Palette.dim,
		TextSize = 14,
		Font = Enum.Font.GothamBold,
	}, bar)
	close.MouseButton1Click:Connect(function() root.Visible = false end)

	local tabBar = inst("Frame", {
		Size = UDim2.new(1, -20, 0, 26),
		Position = UDim2.fromOffset(10, 40),
		BackgroundTransparency = 1,
	}, root)

	local content = inst("Frame", {
		Size = UDim2.new(1, -20, 1, -120),
		Position = UDim2.fromOffset(10, 72),
		BackgroundTransparency = 1,
	}, root)
	M.content = content

	-- drag
	local dragging, dragStart, startPos = false, nil, nil
	bar.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 then
			dragging, dragStart, startPos = true, input.Position, root.Position
		end
	end)
	env.UserInputService.InputChanged:Connect(function(input)
		if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then
			local delta = input.Position - dragStart
			root.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
		end
	end)
	env.UserInputService.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 then dragging = false end
	end)

	local footer = inst("Frame", {
		Size = UDim2.new(1, -20, 0, 34),
		Position = UDim2.new(0, 10, 1, -44),
		BackgroundColor3 = Palette.panel,
		BorderSizePixel = 0,
	}, root)
	round(footer, 5)

	M.status = inst("TextLabel", {
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Text = "booting",
		TextColor3 = Palette.dim,
		TextSize = 11,
		Font = Enum.Font.Code,
		TextXAlignment = Enum.TextXAlignment.Left,
	}, footer)
	inst("UIPadding", { PaddingLeft = UDim.new(0, 10) }, M.status)

	local pages = {
		{ name = "FISH", build = buildFishingPage },
		{ name = "ECONOMY", build = buildEconomyPage },
		{ name = "MOVE", build = buildMovePage },
		{ name = "ESP", build = buildEspPage },
		{ name = "STEALTH", build = buildStealthPage },
		{ name = "LEARN", build = buildLearnPage },
		{ name = "MISC", build = buildMiscPage },
	}

	for index, spec in ipairs(pages) do
		local button = tabButton(tabBar, spec.name, index - 1)
		local page = spec.build()
		M.tabs[spec.name] = button
		M.pages[spec.name] = page
		button.MouseButton1Click:Connect(function() M.select(spec.name) end)
	end

	M.select("FISH")
	return gui
end

function M.toggle()
	if not M.root then return end
	M.root.Visible = not M.root.Visible
end

function M.hide()
	if M.root then M.root.Visible = false end
	if M.notifications then M.notifications.Visible = false end
end

function M.show()
	if M.root then M.root.Visible = true end
	if M.notifications then M.notifications.Visible = true end
end

function M.setStatus(text, tone)
	if not M.status then return end
	M.status.Text = text
	M.status.TextColor3 = (tone == "good" and Palette.good) or (tone == "bad" and Palette.bad) or Palette.dim
end

return M

end)()

__modules["main"] = (function()
-- main: boot, keybinds, status, public API
local env = __require("env")
local util = __require("util")
local config = __require("config")
local scanner = __require("scanner")
local motion = __require("motion")
local minigame = __require("minigame")
local fishing = __require("fishing")
local economy = __require("economy")
local quests = __require("quests")
local esp = __require("esp")
local anti = __require("anti")
local stealth = __require("stealth")
local learn = __require("learn")
local ui = __require("ui")

local M = { version = "2.1.0" }

config.load()
scanner.refresh(true)
ui.build()

util.scheduler.start()

--------------------------------------------------------------------------------
-- keybind
--------------------------------------------------------------------------------

local function bindToggle()
	local keyName = config.get("keybind")
	local ok, key = pcall(function() return Enum.KeyCode[keyName] end)
	if not ok or not key then key = Enum.KeyCode.RightControl end

	local panicName = config.get("panicKey")
	local panicOk, panicKey = pcall(function() return Enum.KeyCode[panicName] end)
	if not panicOk or not panicKey then panicKey = Enum.KeyCode.Delete end

	env.UserInputService.InputBegan:Connect(function(input, processed)
		if processed then return end
		if input.KeyCode == key then
			ui.toggle()
		elseif input.KeyCode == panicKey then
			-- One key, nothing to confirm, no menu to navigate.
			stealth.engagePanic()
		end
	end)
end

bindToggle()

--------------------------------------------------------------------------------
-- character lifecycle
--------------------------------------------------------------------------------

local function applyPhysics()
	local speed = config.get("walkSpeed")
	local jump = config.get("jumpPower")
	if speed and speed ~= 16 then motion.setSpeed(speed) end
	if jump and jump ~= 50 then motion.setJump(jump) end
	if config.get("noclip") then motion.setNoclip(true) end
	if config.get("fly") then motion.startFly(80) end
end

env.LocalPlayer.CharacterAdded:Connect(function()
	task.wait(0.6)
	pcall(applyPhysics)
	if config.get("autoRod") then pcall(function() fishing.rod = scanner.bestRod() end) end
end)

if env.LocalPlayer.Character then
	task.wait(0.4)
	pcall(applyPhysics)
end

--------------------------------------------------------------------------------
-- pause gate: staff detection stops the fisher without destroying state
--------------------------------------------------------------------------------

util.task("gate", 1, function()
	local paused = anti.shouldPause()
	fishing.enabled = not paused
	if paused ~= anti.paused then
		anti.paused = paused
		if paused then
			ui.notify("staff in server - paused", "bad")
		else
			ui.notify("resumed", "good")
		end
	end
end)

--------------------------------------------------------------------------------
-- status
--------------------------------------------------------------------------------

util.task("status", 0.5, function()
	local stats = fishing.stats()
	local text = string.format(
		"%s | rod:%s | casts:%d | catches:%d | %.1f/min",
		stats.state,
		stats.rod or "-",
		stats.casts,
		stats.catches,
		stats.perMinute
	)
	if anti.staffPresent then
		text = text .. " | STAFF"
	end
	text = text .. " | " .. stealth.status()
	ui.setStatus(text, anti.staffPresent and "bad" or (stats.state == "reel" and "good" or nil))
end)

--------------------------------------------------------------------------------
-- public API
--------------------------------------------------------------------------------

local API = {
	version = M.version,
	config = config,
	scanner = scanner,
	motion = motion,
	minigame = minigame,
	fishing = fishing,
	economy = economy,
	quests = quests,
	esp = esp,
	anti = anti,
	stealth = stealth,
	learn = learn,
	ui = ui,

	toggle = function() ui.toggle() end,
	notify = ui.notify,
	save = function() return config.save() end,
	reload = function()
		if env.has.loadstring and env.has.readfile then
			return true
		end
		return false
	end,
	probe = function()
		scanner.refresh(true)
		env.log(scanner.summary())
		env.log("scheduler: %s", util.scheduler.stats())
		for _, remote in ipairs(scanner.remotes.all) do
			env.log("  remote %s", remote:GetFullName())
		end
		for kind, records in pairs(scanner.prompts) do
			for _, record in ipairs(records) do
				env.log("  prompt[%s] %s", kind, record.prompt:GetFullName())
			end
		end
	end,
}

if env.has.getgenv then
	getgenv().FischHub = API
end

env.log("v%s loaded in %s", M.version, env.executor)
ui.notify("Fisch Hub v" .. M.version, "good")

return API

end)()
